package br.com.onda;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.io.*;import java.util.*;import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class RadioCityUiTest {
 private final Instrumentation ins=getInstrumentation();private RadioActivity screen;
 private View find(View root,String text){if(text.contentEquals(root.getContentDescription()==null?"":root.getContentDescription())||root instanceof TextView&&text.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View v=find(((ViewGroup)root).getChildAt(i),text);if(v!=null)return v;}return null;}
 private Object field(String name){try{Field f=RadioActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(screen);}catch(Exception e){throw new RuntimeException(e);}}
 private interface Check{boolean ready();}
 private void waitFor(Check check)throws Exception{for(int i=0;i<300;i++){boolean[] r={false};ins.runOnMainSync(()->r[0]=check.ready());if(r[0])return;Thread.sleep(50);}fail("Radio city UI timed out");}
 @Test public void cityChooserUsesCacheKeepsCountryAndDoesNotMixFavorites()throws Exception{Context c=ins.getTargetContext();SharedPreferences prefs=c.getSharedPreferences("radio",0);String[] keys={"catalog","query","city","catalog_city","city_last_text","city_lookup_query","city_lookup_results"};Map<String,String> old=new HashMap<>();for(String key:keys)old.put(key,prefs.getString(key,null));boolean hadBrazil=prefs.contains("brazil"),oldBrazil=prefs.getBoolean("brazil",true);ByteArrayOutputStream data=new ByteArrayOutputStream();try(InputStream input=c.getAssets().open("radio-cities-br.json")){byte[] buffer=new byte[8192];int n;while((n=input.read(buffer))!=-1)data.write(buffer,0,n);}RadioCity city=RadioCity.local(data.toString("UTF-8"),"Campo Grande MS").get(0);RadioStation station=new RadioStation("city-fixture","Rádio local de teste","https://radio.example.org/live","Brasil","AAC",128,false);
  try{RadioStore.cache(c,Collections.singletonList(station),"",true);prefs.edit().remove("city").putString("catalog_city","").putString("city_last_text","Campo Grande MS").remove("city_lookup_query").remove("city_lookup_results").commit();screen=(RadioActivity)ins.startActivitySync(new Intent(c,RadioActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->find(screen.findViewById(android.R.id.content),"Escolher cidade das rádios")!=null);ins.runOnMainSync(()->find(screen.findViewById(android.R.id.content),"Escolher cidade das rádios").performClick());ins.runOnMainSync(()->find(((Dialog)field("cityDialog")).getWindow().getDecorView(),"Encontrar cidade das rádios").performClick());waitFor(()->field("cityDialog")!=null&&((Dialog)field("cityDialog")).isShowing()&&((Dialog)field("cityDialog")).getWindow().getDecorView().getWidth()>0&&find(((Dialog)field("cityDialog")).getWindow().getDecorView(),"Escolher cidade "+city.label())!=null);
   ins.runOnMainSync(()->{Dialog dialog=(Dialog)field("cityDialog");Rect display=new Rect(),bounds=new Rect();screen.getWindow().getDecorView().getWindowVisibleDisplayFrame(display);dialog.getWindow().getDecorView().getGlobalVisibleRect(bounds);assertTrue(bounds.width()>0&&bounds.height()>0);assertTrue(bounds.width()<=display.width());assertTrue(bounds.height()<=display.height());});
   prefs.edit().putString("catalog_city",city.key()).commit();ins.runOnMainSync(()->find(((Dialog)field("cityDialog")).getWindow().getDecorView(),"Escolher cidade "+city.label()).performClick());waitFor(()->RadioCity.decode(prefs.getString("city",""))!=null&&find(screen.findViewById(android.R.id.content),"Alterar cidade das rádios "+city.label())!=null);ins.runOnMainSync(()->{assertEquals(city.key(),RadioCity.decode(prefs.getString("city","")).key());assertNull(field("active"));assertNotNull(find(screen.findViewById(android.R.id.content),"Ouvir rádio Rádio local de teste"));assertTrue(((TextView)field("status")).getText().toString().contains("50 km"));find(screen.findViewById(android.R.id.content),"Favoritas").performClick();assertFalse(((View)field("cityButton")).isEnabled());find(screen.findViewById(android.R.id.content),"Emissoras").performClick();assertTrue(((View)field("cityButton")).isEnabled());});
   JSONObject report=new JSONObject().put("cityChooserFromExplicitAction",true).put("brazilCityLookupWithoutNetwork",true).put("selectionPreservesCountry",true).put("cachedStationsReused",true).put("nearbyRangeClearlyLabelled",true).put("favoritesRemainSeparate",true).put("dialogWithinScreen",true);try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"radio-city-ui.json"))){out.write(report.toString(2).getBytes("UTF-8"));}
  }finally{if(screen!=null)ins.runOnMainSync(screen::finish);SharedPreferences.Editor e=prefs.edit();for(String key:keys)if(old.get(key)==null)e.remove(key);else e.putString(key,old.get(key));if(hadBrazil)e.putBoolean("brazil",oldBrazil);else e.remove("brazil");e.commit();}
 }
}
